/* 1. Peça ao usuário um número e exiba sua tabuada completa (de 1 a 10) usando um
laço for. Em seguida, pergunte se ele deseja ver outra tabuada e repita enquanto
a resposta for "sim". */

const prompt = require('prompt-sync')();

let resposta = 'sim';

while (resposta.toLowerCase() == 'sim'){
    let numero = Number(prompt("Insira a uma numero de 1 a 10:  "));

    console.log(`Tabuada do ${numero} :`);
    for(let i = 0 ; i <= 10 ; i++){
    console.log( `${numero} x ${i} = ${numero  * i}`);
    }
    resposta = prompt("Deseja ver outra tabuada? (sim/não) : ");
}

/* 2. Leia um número inteiro positivo e, usando um laço while, calcule e exiba quantos
dígitos ele possui. Trate o caso do número zero (que possui 1 dígito). */

const prompt = require('prompt-sync')();
let numeroInteiro = Number(prompt("Insira um numero inteiro positivo:  "));
let contador = 0;

if (numeroInteiro == 0){
    contador = 1;
}
else{
    while (numeroInteiro > 0){
            contador++;
            numeroInteiro = Math.floor(numeroInteiro/10);
          }
    }
console.log(`O número possui ${contador} dígito(s).`);

/*3. Peça ao usuário quantos termos da sequência de Fibonacci deseja ver e exiba-os
usando um laço for. Exemplo: 1, 1, 2, 3, 5, 8, 13... */

const prompt = require('prompt-sync')();
let termos = Number(prompt("Quantos termos da sequência de Fibonacci deseja ver?  "));

let a = 1;
let b = 1;

for (let i = 1; i <= termos; i++){
    console.log(a);

    let proximo = a + b;
    a = b;
    b = proximo;
}

/* 4. Defina uma senha fixa no código. Peça ao usuário que a digite e, usando um laço
do...while, permita no máximo 3 tentativas. Exiba se ele acertou ou se esgotou as
tentativas. */

const prompt = require('prompt-sync')();

const senhaCorreta = "0531";

let tentativa;
let tentativas = 0;

do {
    tentativa = prompt("Digite a senha:");
    tentativas++;

    if (tentativa == senhaCorreta) {
        console.log("Senha correta! Acesso liberado.");
        break;
    }

} while (tentativas < 3);

if (tentativa != senhaCorreta) {
    console.log("Você esgotou suas 3 tentativas.");
}

/* 5. Leia um número N e exiba todos os números primos entre 2 e N usando laços
aninhados (for dentro de for). Exiba também a quantidade total de primos
encontrados. */

const prompt = require('prompt-sync')();

let N = Number(prompt("Digite um número: "));
let quantPrimos = 0;

for (let i = 2; i <= N; i++) {

    let divisores = 0;

    for (let j = 1; j <= i; j++) {

        if (i % j == 0) {
            divisores++;
        }

    }

    if (divisores == 2) {
        console.log(i);
        quantPrimos++;
    }

}

console.log(`Total de números primos: ${quantPrimos}`);

/* 6. Crie um array e leia via laço o nome e a nota de 5 alunos. Ao final, exiba: a média
da turma, o nome do aluno com maior nota e o nome do aluno com menor nota.
Não use funções prontas como Math.max(). */

const prompt = require('prompt-sync')();

let nomes = [];
let notas = [];

let soma = 0;

for (let i = 0; i < 5; i++) {
    nomes[i] = prompt(`Digite o nome do aluno ${i + 1}: `);
    notas[i] = Number(prompt(`Digite a nota de ${nomes[i]}: `));

    soma += notas[i];
}

let maiorNota = notas[0];
let menorNota = notas[0];

let alunoMaior = nomes[0];
let alunoMenor = nomes[0];

for (let i = 1; i < 5; i++) {

    if (notas[i] > maiorNota) {
        maiorNota = notas[i];
        alunoMaior = nomes[i];
    }

    if (notas[i] < menorNota) {
        menorNota = notas[i];
        alunoMenor = nomes[i];
    }
}

let media = soma / 5;

console.log(`Média da turma: ${media.toFixed(2)}`);
console.log(`Maior nota: ${alunoMaior} (${maiorNota})`);
console.log(`Menor nota: ${alunoMenor} (${menorNota})`);

/* 7. Simule um carrinho de compras: leia nomes e preços de produtos em um laço até
o usuário digitar "sair". Armazene em arrays. Ao final, liste todos os itens, exiba o
subtotal, aplique 10% de desconto se houver mais de 3 itens e mostre o total a
pagar. */

const prompt = require('prompt-sync')();

let produtos = [];
let precos = [];

let nomeProduto;
let subtotal = 0;

while (true) {

    nomeProduto = prompt("Digite o nome do produto (ou 'sair'): ");

    if (nomeProduto.toLowerCase() == "sair") {
        break;
    }

    let preco = Number(prompt("Digite o preço: "));

    produtos.push(nomeProduto);
    precos.push(preco);

    subtotal += preco;
}

console.log("\n--- CARRINHO DE COMPRAS ---");

for (let i = 0; i < produtos.length; i++) {
    console.log(`${produtos[i]} - R$ ${precos[i].toFixed(2)}`);
}

let desconto = 0;

if (produtos.length > 3) {
    desconto = subtotal * 0.10;
}

let total = subtotal - desconto;

console.log(`\nSubtotal: R$ ${subtotal.toFixed(2)}`);
console.log(`Desconto: R$ ${desconto.toFixed(2)}`);
console.log(`Total a pagar: R$ ${total.toFixed(2)}`);

 /* 8. Leia uma palavra, armazene seus caracteres em um array e, percorrendo-o de
trás para frente com um laço for, monte a palavra invertida. Exiba a palavra
original, a invertida e informe se ela é um palíndromo. */

const prompt = require('prompt-sync')();

let palavra = prompt("Digite uma palavra: ");

let letras = [];
let invertida = "";

for (let i = 0; i < palavra.length; i++) {
    letras.push(palavra[i]);
}

for (let i = letras.length - 1; i >= 0; i--) {
    invertida += letras[i];
}

console.log(`A palavra original é: ${palavra}`);
console.log(`A palavra invertida é: ${invertida}`);

if ( invertida == palavra ) {
    console.log("É palíndromo");
} else {
    console.log("Não é palíndromo");
}

 /* 9. Sorteie um número entre 1 e 100 com Math.random(). Usando um laço do...while,
peça ao usuário para adivinhar; a cada tentativa, diga se o número é maior ou
menor. Registre as tentativas em um array e, ao acertar, exiba o histórico e quantas tentativas foram necessárias. */

const prompt = require('prompt-sync')();

let numeroSorteado = Math.floor(Math.random() * 100) + 1;

let tentativa;
let historico = [];

do{

tentativa = Number(prompt("Digite um número entre 1 e 100: "));
historico.push(tentativa);

if (tentativa < numeroSorteado) {
    console.log('O numero sorteado é MAIOR!');
}
else if (tentativa > numeroSorteado) {
    console.log('O numero sorteado é MENOR!')
}
}while(tentativa != numeroSorteado);

console.log("Acertou!");
console.log("Histórico de Tentativas: ");
console.log(historico);
console.log(`O número de tentativas foi de: ${historico.length}`);

 /* 10. Crie uma matriz 3×4 (3 alunos, 4 notas cada). Leia os valores via laços aninhados.
Calcule e exiba a média de cada aluno, a média geral da turma e qual aluno teve
o melhor desempenho. */

const prompt = require('prompt-sync')();

let notas = [];

let mediaGeral = 0;
let melhorMedia = 0;
let melhorAluno = 0;

for (let aluno = 0; aluno < 3; aluno++) {

    notas[aluno] = [];

    let soma = 0;

    console.log(`Aluno ${aluno + 1}`);

    for (let nota = 0; nota < 4; nota++) {

        notas[aluno][nota] = Number(
            prompt(`Digite a nota ${nota + 1}: `)
        );

        soma += notas[aluno][nota];
    }

    let mediaAluno = soma / 4;

    console.log(
        `Média do aluno ${aluno + 1}: ${mediaAluno.toFixed(2)}`
    );

    mediaGeral += mediaAluno;

    if (aluno === 0 || mediaAluno > melhorMedia) {
        melhorMedia = mediaAluno;
        melhorAluno = aluno + 1;
    }
}

mediaGeral = mediaGeral / 3;

console.log(`\nMédia geral da turma: ${mediaGeral.toFixed(2)}`);
console.log(`Melhor desempenho: Aluno ${melhorAluno}`);
console.log(`Média do melhor aluno: ${melhorMedia.toFixed(2)}`);


